<?php
namespace qqworld_collector\module\static_cache; use qqworld_collector\lib; class rest_api extends lib { var $abspath; public function init() { add_action( 'rest_api_init', array($this, 'rest_api_init') ); } public function rest_api_init() { $namespace = 'static-cache/v1'; register_rest_route( $namespace, 'minify/html/debug', array( 'methods' => 'GET', 'callback' => array($this, 'minify_html_debug'), 'update_callback' => null, 'permission_callback' => '__return_true', 'schema' => null ) ); } public function minify_html_debug() { $content = file_get_contents(home_url()); $GLOBALS['QC']->options->qc_static_cache_minify_html = 1; $content = $this->minify_html($content); print $content; } } ?>